def check_A(A):
    # Check if A = floor(2^(A/2))
    return A == int(2**(A/2))

print("Testing for integer solutions A >= 2 where A = floor(2^(A/2))")
solutions = []
for A in range(2, 11):
    if check_A(A):
        solutions.append(A)

# Check values beyond 10 to confirm divergence
print("\nTesting A=11, 12, 13:")
print(f"A=11: floor(2^5.5) = floor(45.25) = 45. Expected 11. Match: {check_A(11)}")
print(f"A=12: floor(2^6) = 64. Expected 12. Match: {check_A(12)}")
print(f"A=13: floor(2^6.5) = floor(90.5) = 90. Expected 13. Match: {check_A(13)}")
